import Foundation

struct StudyLesson: Identifiable {
    let id: String
    let title: String
    var isComplete: Bool
}
struct StudyCourse: Identifiable {
    let id: String
    let title: String
    var lessons: [StudyLesson]
    var completedCount: Int { lessons.filter(\.isComplete).count }
    var progressPercent: Double { lessons.isEmpty ? 0 : Double(completedCount) / Double(lessons.count) * 100 }
}

func searchCourses(_ courses: [StudyCourse], query: String) -> [StudyCourse] {
    courses.filter { $0.title.localizedCaseInsensitiveContains(query) }
}
let courses = [StudyCourse(id: "swift", title: "Swift", lessons: [StudyLesson(id: "one", title: "First program", isComplete: true), StudyLesson(id: "two", title: "Optionals", isComplete: false)])]
for course in searchCourses(courses, query: "swift") { print("\(course.title): \(Int(course.progressPercent))%") }
